import sys
from collections import deque

def main():
    input = sys.stdin.read().splitlines()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        while ptr < len(input) and not input[ptr].strip():
            ptr += 1
        n, k = map(int, input[ptr].split())
        ptr += 1
        adj = [[] for _ in range(n+1)]
        for __ in range(n-1):
            u, v = map(int, input[ptr].split())
            adj[u].append(v)
            adj[v].append(u)
            ptr += 1

        leaves = deque()
        degree = [0]*(n+1)
        for u in range(1, n+1):
            degree[u] = len(adj[u])
            if degree[u] <= 1:
                leaves.append(u)

        remaining = n
        for _ in range(k):
            if not leaves:
                break
            next_leaves = deque()
            while leaves:
                u = leaves.popleft()
                remaining -= 1
                for v in adj[u]:
                    degree[v] -= 1
                    if degree[v] == 1:
                        next_leaves.append(v)
            leaves = next_leaves
        print(remaining)

if __name__ == '__main__':
    main()
